	@Test
	void groupedValuesFoldMustExecuteOnTheCheckedInvocation() {
		try (GroupedFixture fixture = new GroupedFixture()) {
			Group group = counted(singleFilter(List.of(GROUP_A, GROUP_B), false), "e", true);
			QueryEvaluationStep step = fixture.prepare(group);
			GroupObservation observed = observe("safe-distinct", group, step, EmptyBindingSet.getInstance());
			SoftAssertions softly = new SoftAssertions();
			softly.assertThat(maps(observed.rows()))
					.as("the independently derived aggregate bag")
					.containsExactly(Map.of("count", integer(2)));
			softly.assertThat(observed.planned()).as("the actual root is a native Group").contains("NativeGroup(");
			softly.assertThat(observed.nativeDelta())
					.as("the checked invocation opened the native Group")
					.isPositive();
			softly.assertThat(observed.path())
					.as("the checked invocation selected a native path")
					.isNotNull()
					.doesNotContain("genericFallback(");
			softly.assertThat(observed.runtime())
					.as("the same invocation completed its native runtime plan")
					.isNotNull()
					.contains("LMDB native physical plan (executed)", "status: COMPLETED", "opens: 1");
			softly.assertThat(actualOrder(observed.runtime()))
					.as("the exact-domain producer was actually opened")
					.doesNotContain("<not opened")
					.contains("ExactDomainDrive(");
			softly.assertAll();
		}
	}

