	@Test
	void projectedGroupHostPreservesFinalMappingCompatibility() {
		try (GroupedFixture fixture = new GroupedFixture()) {
			BindingSet a = binding("g", GROUP_A);
			BindingSet b = binding("g", GROUP_B);
			SoftAssertions nativeAssertions = new SoftAssertions();
			for (boolean hosted : List.of(false, true)) {
				for (boolean duplicate : List.of(false, true)) {
					Group group = projectedGroup(duplicate);
					Group genericGroup = group.clone();
					TupleExpr genericRoot = hosted ? new QueryRoot(genericGroup) : genericGroup;
					TupleExpr nativeRoot = hosted ? new QueryRoot(group) : group;
					Projection genericProjection = (Projection) genericGroup.getArg();
					assertThat(genericProjection.isSubquery()).isTrue();
					QueryEvaluationStep genericProjectionStep = fixture.generic.precompile(genericProjection,
							fixture.context);
					QueryEvaluationStep genericStep = fixture.generic.precompile(genericRoot, fixture.context);
					int boundCount = duplicate ? 2 : 1;
					Map<String, Value> bound = Map.of("g", GROUP_A, "n", integer(boundCount));
					Map<String, Value> aUnbound = Map.of("g", GROUP_A, "n", integer(1));
					record Case(String name, BindingSet input, List<Map<String, Value>> expected) {
					}
					List<Case> cases = List.of(
							new Case("absent", EmptyBindingSet.getInstance(),
									List.of(bound, Map.of("n", integer(1)))),
							new Case("a", a, duplicate ? List.of(bound, aUnbound) : List.of(bound)),
							new Case("b", b, List.of(bound, Map.of("g", GROUP_B, "n", integer(1)))),
							new Case("a-again", a, duplicate ? List.of(bound, aUnbound) : List.of(bound)));
					List<Map<String, Value>> projected = duplicate
							? List.of(Map.of("g", GROUP_A), Map.of("g", GROUP_A), Map.of())
							: List.of(Map.of("g", GROUP_A), Map.of());
					SoftAssertions genericAssertions = new SoftAssertions();
					for (Case test : cases) {
						GroupObservation inputRows = observe(
								"projection-" + hosted + "/" + duplicate + "/" + test.name(),
								genericProjection, genericProjectionStep, test.input());
						genericAssertions.assertThat(maps(inputRows.rows()))
								.as("the projection exposes h AS g, not caller g: %s", test.name())
								.containsExactlyInAnyOrderElementsOf(projected);
						GroupObservation generic = observe("generic-projection-group-" + hosted + "/" + duplicate + "/"
								+ test.name(), genericGroup, genericStep, test.input());
						genericAssertions.assertThat(maps(generic.rows()))
								.as("the direct generic Group host bag %s", test.name())
								.containsExactlyInAnyOrderElementsOf(test.expected());
					}
					// Stop before interpreting native behavior if either source-derived generic premise is false.
					genericAssertions.assertAll();
					group.setRuntimeTelemetryEnabled(true);
					group.setExecutionSummaryEnabled(true);
					QueryEvaluationStep nativeStep = fixture.prepare(nativeRoot);
					for (Case test : cases) {
						if (nativeRoot != group) {
							group.setStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN, null);
							group.setStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH, null);
						}
						long groupBefore = Math.max(0L, group.getLongMetricActual("nativeInvocationsActual"));
						GroupObservation observed = observe("projection-group-" + hosted + "/" + duplicate + "/"
								+ test.name(), nativeRoot, nativeStep, test.input());
						long groupDelta = Math.max(0L, group.getLongMetricActual("nativeInvocationsActual"))
								- groupBefore;
						String groupPath = group.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH);
						String groupRuntime = group.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN);
						String groupPlanned = group.getStringMetricPlanned("nativePhysicalPlan");
						System.out.printf("projection-group innerDelta=%d innerPath=%s innerPlan=%s innerRuntime=%s%n",
								groupDelta, groupPath, groupPlanned, groupRuntime);
						nativeAssertions.assertThat(maps(observed.rows()))
								.as("the native Group host bag %s / %s / %s", hosted, duplicate, test.name())
								.containsExactlyInAnyOrderElementsOf(test.expected());
						boolean preparedGroup = observed.planned() != null
								&& observed.planned().contains("NativeGroup(")
								|| groupPlanned != null && groupPlanned.contains("NativeGroup(");
						nativeAssertions.assertThat(preparedGroup)
								.as("the checked root contains a native Group")
								.isTrue();
						boolean rootNative = completedNativeGroup(observed.nativeDelta(), observed.path(),
								observed.runtime());
						boolean innerNative = completedNativeGroup(groupDelta, groupPath, groupRuntime);
						boolean fallback = isGenericFallback(observed.path()) || isGenericFallback(groupPath);
						if (!test.name().equals("absent") && fallback) {
							nativeAssertions.assertThat(fallback)
									.as("a collision may safely decline natively")
									.isTrue();
						} else {
							nativeAssertions.assertThat(rootNative || innerNative)
									.as("the same host or inner Group completed a native invocation")
									.isTrue();
						}
					}
				}
			}
			nativeAssertions.assertAll();
		}
	}

