	@Test
	void contextOccurrencesKeepTheirOwnBindingAndNilSemantics() {
		try (GroupedFixture fixture = occurrenceFixture()) {
			StatementPattern named = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("e"),
					Var.of("g", CONTEXT_P, true, true), Var.of("x"), Var.of("g"));
			StatementPattern nullable = new StatementPattern(StatementPattern.Scope.DEFAULT_CONTEXTS, Var.of("e"),
					Var.of("predicate", CONTEXT_P, true, true), Var.of("x"), Var.of("g"));
			StatementPattern alias = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("g"),
					Var.of("predicate", CONTEXT_P, true, true), Var.of("x"), Var.of("g"));
			StatementPattern fixedNil = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("e"),
					Var.of("predicate", CONTEXT_P, true, true), Var.of("x"), Var.of("g", RDF4J.NIL));
			StatementPattern constantNil = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("g"),
					Var.of("predicate", CONTEXT_P, true, true), Var.of("x"),
					Var.of("g", RDF4J.NIL, true, true));
			record Case(String name, StatementPattern pattern, List<Map<String, Value>> expected) {
			}
			List<Case> cases = List.of(
					new Case("constant shares context name", named, List.of(
							Map.of("e", GROUP_A, "g", GROUP_GRAPH, "x", GROUP_A, "t", GROUP_A),
							Map.of("e", GROUP_B, "g", GROUP_GRAPH, "x", GROUP_B, "t", GROUP_B),
							Map.of("e", GROUP_GRAPH, "g", GROUP_GRAPH, "x", GROUP_A, "t", GROUP_A))),
					new Case("default context may be unbound", nullable, List.of(
							Map.of("e", GROUP_A, "g", GROUP_GRAPH, "x", GROUP_A, "t", GROUP_A),
							Map.of("e", GROUP_B, "g", GROUP_GRAPH, "x", GROUP_B, "t", GROUP_B),
							Map.of("e", GROUP_GRAPH, "g", GROUP_GRAPH, "x", GROUP_A, "t", GROUP_A),
							Map.of("e", GROUP_C, "x", GROUP_C, "t", GROUP_C))),
					new Case("context and subject are the same variable", alias, List.of(
							Map.of("g", GROUP_GRAPH, "x", GROUP_A, "t", GROUP_A))),
					new Case("valued NIL context is a binding", fixedNil, List.of(
							Map.of("e", GROUP_C, "g", RDF4J.NIL, "x", GROUP_C, "t", GROUP_C))),
					new Case("constant NIL does not constrain its namesake subject", constantNil, List.of(
							Map.of("g", GROUP_C, "x", GROUP_C, "t", GROUP_C))));
			for (Case test : cases) {
				Join owner = occurrenceOwner(test.pattern(), "x", List.of(GROUP_A, GROUP_B, GROUP_C));
				Join generic = owner.clone();
				assertThat(rows(fixture.generic.precompile(generic, fixture.context))).as("generic %s", test.name())
						.containsExactlyInAnyOrderElementsOf(test.expected());
				assertThat(rows(fixture.prepare(owner))).as("prepared %s", test.name())
						.containsExactlyInAnyOrderElementsOf(test.expected());
			}
		}
	}

	private GroupedFixture occurrenceFixture() {
		return new GroupedFixture(VF.createStatement(GROUP_P, GROUP_P, GROUP_B),
				VF.createStatement(GROUP_A, GROUP_P, GROUP_P), VF.createStatement(GROUP_P, GROUP_Q, GROUP_TAG),
				VF.createStatement(GROUP_GRAPH, CONTEXT_P, GROUP_A, GROUP_GRAPH));
	}

	private static Join occurrenceOwner(StatementPattern pattern, String filterName) {
		return occurrenceOwner(pattern, filterName, List.of(GROUP_A, GROUP_B, GROUP_P));
	}

	private static Join occurrenceOwner(StatementPattern pattern, String filterName, List<Value> domain) {
		Filter filter = new Filter(groupValues(domain, false),
				new Compare(Var.of(filterName), Var.of("t")));
		filter.setConditionBindingScope(ConditionBindingScope.retain(Set.of(filterName, "t")));
		return new Join(pattern, filter);
	}

