	@Test
	void leftDeepOwnerFiltersRequireOneValuesWitness() {
		try (GroupedFixture fixture = new GroupedFixture()) {
			record Case(String name, String suffix, List<Value> domain, boolean undef, int expected) {
			}
			List<Case> cases = List.of(
					new Case("split", "split", List.of(A, B), false, 0),
					new Case("same", "same", List.of(A, B), false, 1),
					new Case("split-duplicates", "split", List.of(A, A, B), false, 0),
					new Case("same-duplicates", "same", List.of(A, A, B), false, 1),
					new Case("split-undef", "split", List.of(A, A, B), true, 0),
					new Case("same-undef", "same", List.of(A, A, B), true, 1));
			BindingSet emptyMarker = BindingFrameBindings.withSubstitutionDomain(EmptyBindingSet.getInstance(),
					Set.of(), fixture.context);
			BindingSet probe = BindingFrameBindings.push(new BindingFrameBindings.Scope(), emptyMarker,
					binding("t", GROUP_C), fixture.context);
			SoftAssertions softly = new SoftAssertions();
			for (Case test : cases) {
				Filter first = new Filter(pattern("e", "x", VF.createIRI("urn:witness:p-" + test.suffix())),
						new Compare(Var.of("x"), Var.of("t")));
				Filter second = new Filter(pattern("e", "y", VF.createIRI("urn:witness:q-" + test.suffix())),
						new Compare(Var.of("y"), Var.of("t")));
				Join firstOwner = new Join(groupValues(test.domain(), test.undef()), first);
				Join secondOwner = new Join(firstOwner, second);
				Group group = counted(secondOwner, "e", true);
				assertFilterOwnerAndFrame(group, first, firstOwner, "x");
				assertFilterOwnerAndFrame(group, second, secondOwner, "y");

				// These separately prepared scalar checks establish the intended values in each owner frame.
				// They do not instrument or replace either filter in the checked native invocation.
				var firstScalar = fixture.generic.precompile(first.getCondition(), fixture.context);
				var secondScalar = fixture.generic.precompile(second.getCondition(), fixture.context);
				assertThat(firstScalar.evaluate(pair("x", A, "t", A))).isEqualTo(VF.createLiteral(true));
				assertThat(firstScalar.evaluate(pair("x", A, "t", B))).isEqualTo(VF.createLiteral(false));
				Value y = test.suffix().equals("split") ? B : A;
				assertThat(secondScalar.evaluate(pair("y", y, "t", A)))
						.isEqualTo(VF.createLiteral(test.expected() == 1));

				Join genericFirstOwner = firstOwner.clone();
				GroupObservation firstRows = observe("generic-left-owner-" + test.name(), genericFirstOwner,
						fixture.generic.precompile(genericFirstOwner, fixture.context), EmptyBindingSet.getInstance());
				List<Map<String, Value>> expectedFirst = new ArrayList<>();
				for (Value value : test.domain()) {
					if (value.equals(A)) {
						expectedFirst.add(Map.of("e", test.suffix().equals("split") ? SPLIT : SAME, "x", A, "t", A));
					}
				}
				assertThat(maps(firstRows.rows())).as("first owner supplies the actual t row: %s", test.name())
						.containsExactlyInAnyOrderElementsOf(expectedFirst);

				Group genericGroup = group.clone();
				QueryEvaluationStep genericStep = fixture.generic.precompile(genericGroup, fixture.context);
				QueryEvaluationStep nativeStep = fixture.prepare(group);
				for (BindingSet input : List.of(EmptyBindingSet.getInstance(), probe)) {
					String label = test.name() + (input == probe ? "/probe-only" : "/absent");
					Map<String, Value> expected = Map.of("count", integer(test.expected()));
					GroupObservation generic = observe("generic-left-deep-" + label, genericGroup, genericStep, input);
					assertThat(maps(generic.rows())).as("generic same-row witness: %s", label)
							.containsExactly(expected);
					GroupObservation nativeResult = observe("left-deep-" + label, group, nativeStep, input);
					softly.assertThat(maps(nativeResult.rows()))
							.as("native same-row witness: %s", label)
							.containsExactly(expected);
					if (input == probe) {
						assertProbeFrame(softly, generic.rows(), "generic left-deep " + label);
						assertProbeFrame(softly, nativeResult.rows(), "native left-deep " + label);
					}
					recordActualValuesRoute(label, nativeResult);
				}
			}
			softly.assertAll();
		}
	}

