	@Test
	void groupedValuesReuseOriginalCallerAndFrameAuthority() {
		try (GroupedFixture fixture = new GroupedFixture()) {
			Group group = counted(singleFilter(List.of(GROUP_A, GROUP_B), false), "e", true);
			QueryEvaluationStep step = fixture.prepare(group);
			Group genericGroup = group.clone();
			QueryEvaluationStep genericStep = fixture.generic.precompile(genericGroup, fixture.context);
			QueryEvaluationContext context = fixture.context;
			MapBindingSet matching = binding("t", GROUP_A);
			MapBindingSet matchingB = binding("t", GROUP_B);
			MapBindingSet conflicting = binding("t", GROUP_C);
			Value remote = RemoteBNode.newResponseScope(new BlankNodeAllocationScope(), VF, new Object(), true)
					.map(VF.createBNode("group-protected"));
			MapBindingSet protectedInput = binding("t", remote);
			BindingSet marked = BindingFrameBindings.withSubstitutionDomain(EmptyBindingSet.getInstance(), Set.of(),
					context);
			BindingSet markedMatching = BindingFrameBindings.withSubstitutionDomain(matching, Set.of(), context);
			BindingSet markedConflicting = BindingFrameBindings.withSubstitutionDomain(conflicting, Set.of(), context);
			BindingSet probe = BindingFrameBindings.push(new BindingFrameBindings.Scope(), marked,
					binding("t", GROUP_C), context);
			BindingSet graph = GraphFrameBindings.supply(new MapBindingSet(), "g", GROUP_GRAPH);
			record Case(String name, BindingSet input, Map<String, Value> expected) {
			}
			List<Case> cases = List.of(
					new Case("absent-first", EmptyBindingSet.getInstance(), Map.of("count", integer(2))),
					new Case("compatible-a", matching, Map.of("t", GROUP_A, "count", integer(1))),
					new Case("compatible-b", matchingB, Map.of("t", GROUP_B, "count", integer(1))),
					new Case("compatible-a-again", matching, Map.of("t", GROUP_A, "count", integer(1))),
					new Case("conflicting", conflicting, Map.of("t", GROUP_C, "count", integer(0))),
					new Case("protected", protectedInput, Map.of("t", remote, "count", integer(0))),
					new Case("absent-again", EmptyBindingSet.getInstance(), Map.of("count", integer(2))),
					new Case("empty-marker", marked, Map.of("count", integer(2))),
					new Case("empty-marker-visible-a", markedMatching, Map.of("t", GROUP_A, "count", integer(1))),
					new Case("empty-marker-visible-c", markedConflicting, Map.of("t", GROUP_C, "count", integer(0))),
					new Case("unauthorized-probe", probe, Map.of("count", integer(2))),
					new Case("disjoint-caller", binding("outside", GROUP_C),
							Map.of("outside", GROUP_C, "count", integer(2))),
					new Case("supplied-graph", graph, Map.of("g", GROUP_GRAPH, "count", integer(2))),
					new Case("absent-after-graph", EmptyBindingSet.getInstance(), Map.of("count", integer(2))));
			SoftAssertions softly = new SoftAssertions();
			softly.assertThat(BindingFrameBindings.substitutionDomain(marked)).isEmpty();
			softly.assertThat(BindingFrameBindings.substitutionDomain(markedMatching)).isEmpty();
			softly.assertThat(markedMatching.getValue("t")).isEqualTo(GROUP_A);
			softly.assertThat(markedConflicting.getValue("t")).isEqualTo(GROUP_C);
			softly.assertThat(BindingFrameBindings.substitutionDomain(probe)).isEqualTo(Set.of());
			softly.assertThat(probe.getValue("t")).isNull();
			softly.assertThat(BindingFrameBindings.probeValue(probe, "t")).isEqualTo(GROUP_C);
			for (Case test : cases) {
				GroupObservation generic = observe("generic-" + test.name(), genericGroup, genericStep, test.input());
				GroupObservation observed = observe(test.name(), group, step, test.input());
				softly.assertThat(maps(generic.rows()))
						.as("generic logical Group: %s", test.name())
						.containsExactly(test.expected());
				softly.assertThat(maps(observed.rows()))
						.as("reused prepared Group: %s", test.name())
						.containsExactly(test.expected());
				if (test.name().equals("unauthorized-probe")) {
					assertProbeFrame(softly, generic.rows(), "generic " + test.name());
					assertProbeFrame(softly, observed.rows(), "native " + test.name());
				}
				if (test.name().startsWith("absent-") || test.name().equals("empty-marker")
						|| test.name().equals("unauthorized-probe") || test.name().equals("disjoint-caller")
						|| test.name().equals("supplied-graph")) {
					softly.assertThat(observed.nativeDelta())
							.as("safe reused Group executes natively: %s", test.name())
							.isPositive();
					softly.assertThat(actualOrder(observed.runtime()))
							.as("safe reused Group opens its exact-domain producer: %s", test.name())
							.doesNotContain("<not opened")
							.contains("ExactDomainDrive(");
				}
				if (test.name().equals("protected")) {
					if (observed.rows().size() == 1) {
						softly.assertThat(observed.rows().get(0).getValue("t")).isSameAs(remote);
					}
				}
				if (test.name().equals("supplied-graph") && observed.rows().size() == 1) {
					softly.assertThat(GraphFrameBindings.isSupplied(observed.rows().get(0), "g")).isTrue();
				}
			}
			softly.assertAll();
		}
	}

